UPDATE institution
institution_no = #{institutionNo}, institution_name = #{institutionName}, institution_type = #{institutionType}, contact_person = #{contactPerson}, contact_phone = #{contactPhone}, contact_email = #{contactEmail}, region = #{region}, address = #{address}, institution_status = #{institutionStatus}, actual_beds = #{actualBeds}, open_beds = #{openBeds}, created_by = #{createdBy}, remark = #{remark},
