mapper.select:
SELECT i.institution_no AS institutionNo, i.institution_name AS institutionName, i.region AS region, COALESCE(SUM( CASE WHEN c.id IS NOT NULL AND ( (#{year} IS NULL) OR (YEAR(c.sign_date) <= #{year} AND YEAR(c.expire_date) >= #{year}) OR (YEAR(c.sign_date) = #{year}) OR (YEAR(c.expire_date) = #{year}) ) THEN c.contract_amount ELSE 0 END ), 0) AS annualDue, COALESCE(( SELECT SUM(cf.fee_amount) FROM contract_fee cf WHERE cf.institution_no = i.institution_no AND (#{year} IS NULL OR YEAR(cf.fee_date) = #{year}) ), 0) AS annualCollected, COALESCE(SUM( CASE WHEN c.id IS NOT NULL AND ( (#{year} IS NULL) OR (YEAR(c.sign_date) <= #{year} AND YEAR(c.expire_date) >= #{year}) OR (YEAR(c.sign_date) = #{year}) OR (YEAR(c.expire_date) = #{year}) ) THEN c.contract_amount ELSE 0 END ), 0) - COALESCE(( SELECT SUM(cf.fee_amount) FROM contract_fee cf WHERE cf.institution_no = i.institution_no AND (#{year} IS NULL OR YEAR(cf.fee_date) = #{year}) ), 0) AS annualArrears, CASE WHEN COALESCE(SUM( CASE WHEN c.id IS NOT NULL AND ( (#{year} IS NULL) OR (YEAR(c.sign_date) <= #{year} AND YEAR(c.expire_date) >= #{year}) OR (YEAR(c.sign_date) = #{year}) OR (YEAR(c.expire_date) = #{year}) ) THEN c.contract_amount ELSE 0 END ), 0) = 0 THEN '0.00%' ELSE CONCAT(ROUND(COALESCE(( SELECT SUM(cf.fee_amount) FROM contract_fee cf WHERE cf.institution_no = i.institution_no AND (#{year} IS NULL OR YEAR(cf.fee_date) = #{year}) ), 0) / COALESCE(SUM( CASE WHEN c.id IS NOT NULL AND ( (#{year} IS NULL) OR (YEAR(c.sign_date) <= #{year} AND YEAR(c.expire_date) >= #{year}) OR (YEAR(c.sign_date) = #{year}) OR (YEAR(c.expire_date) = #{year}) ) THEN c.contract_amount ELSE 0 END ), 0) * 100, 2), '%') END AS collectionRate FROM institution i LEFT JOIN contract c ON i.institution_no = c.institution_no WHERE i.institution_status = 'NORMAL'
AND i.region = #{region}
AND i.institution_name LIKE CONCAT('%', #{institutionName}, '%')
GROUP BY i.institution_no, i.institution_name, i.region ORDER BY i.institution_no LIMIT #{offset}, #{size}

SELECT COUNT(DISTINCT i.institution_no) FROM institution i WHERE i.institution_status = 'NORMAL'
AND i.region = #{region}
AND i.institution_name LIKE CONCAT('%', #{institutionName}, '%')
